  let zone = FixedOffsetZone.parseSpecifier("UTC+6");
  expect(zone.isValid).toBe(true);
  expect(zone.offset()).toBe(360);
  expect(zone.name).toBe("UTC+6");

  zone = FixedOffsetZone.parseSpecifier("UTC+06");
  expect(zone.isValid).toBe(true);
  expect(zone.offset()).toBe(360);
