  expect(at(1, 6, 12).isInDST).toBe(true);
  expect(at(6, 1, 12).isInDST).toBe(true);
  expect(at(10, 26, 12).isInDST).toBe(true);
  expect(at(10, 27, 12).isInDST).toBe(false);
  expect(at(12, 31, 12).isInDST).toBe(false);
});

